// ZeroNote 状态栏插件 —— 构建脚本。
//
// `tauri_plugin::Builder` 做两件对本插件至关重要的事：
//   ① 在 `permissions/autogenerated/` 下按 COMMANDS 生成权限文件
//      （`set_status_bar_visible` → `allow-set-status-bar-visible`）
//   ② `.android_path("android")` 告诉 Tauri CLI 本插件的 Android 模块在哪 ——
//      CLI 据此自动写入 `gen/android/tauri.settings.gradle` 的 include 行，
//      所以 **不需要手改 gradle**（官方 dialog 插件走的同一条路）。
const COMMANDS: &[&str] = &["set_status_bar_visible"];

fn main() {
  tauri_plugin::Builder::new(COMMANDS)
    .android_path("android")
    .build();
}
